# Code generated by Claude
"""
Measurement of the carry slice against two real carries (David 2026-10-25, part 2): the recorded place episodes of data/held_beaker/ (TASK_CFG's stance and the overlay's pick), replayed (no new episode),
and for every tick from the pick's UP to the end of the place's OVER (the beaker in the hand, carried) the distance, seen from above, by which the hand's pad centre, the beaker's bottom (its centre and its
outer rim) and the forearm (points along the elbow to wrist line) lie outside the carry slice (src/stance_select.slice_distance, no margin): apex at the left arm's shoulder, edges to the beaker's xy at the
pick's grasp and at the place's set-down, arc of the larger shoulder-to-hand distance. Also whether the hand path is an arc around the shoulder, a straight line, or neither. Nothing is adjusted.

    MUJOCO_GL=egl python experiments/carry_slice_check.py
"""
import json
import math
import os
import sys
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))
if not os.environ.get("DISPLAY"):
    os.environ.setdefault("MUJOCO_GL", "egl")

import numpy as np  # noqa: E402

import src.replay as replay  # noqa: E402
from src.gripper_geometry import gripper_frame  # noqa: E402
from src.robot_helpers import arm_ids  # noqa: E402
from src.stance_select import shoulder_xy, slice_distance  # noqa: E402
from src.task_config import BEAKER_CFG  # noqa: E402
from src.stance_finder import robot_geometry  # noqa: E402

RUNS = {"TASK_CFG stance": PROJECT_ROOT / "data" / "held_beaker" / "task_cfg", "overlay's pick": PROJECT_ROOT / "data" / "held_beaker" / "bench_region"}


def measure(run_dir):
    meta = json.loads((run_dir / "recording" / "meta.json").read_text())
    labels = meta["labels"]
    tick0 = next(l["tick"] for l in labels if l["label"].startswith("2/4 PICK: UP"))
    tick1 = next(l["tick"] for l in labels if l["label"].startswith("4/4 PLACE: DOWN"))
    close_tick = next(l["tick"] for l in labels if l["label"].startswith("2/4 PICK: UP")) - 1
    S = {"rows": [], "model": None, "grasp_xy": None, "tick_end": None}
    orig = replay.run_loop

    def run_loop(model, data, sources, cfg, viewer=None):
        import mujoco
        ids = arm_ids(model, "left")
        jan = [ids["jnt"][i] for i in (0, 3, 5)]                                   # shoulder (joint 1), elbow (joint 4), wrist (joint 6) anchors
        gf = gripper_frame(model, "left")
        tcp = model.body("openarm_left_hand_tcp").id
        bj = model.joint("task_beaker_free").qposadr[0]
        rg = robot_geometry(model)
        inner = cfg["replay"]["on_tick_end"]

        def hook(frame, data_):
            inner(frame, data_)
            if close_tick <= frame <= tick1:
                R = data_.xmat[tcp].reshape(3, 3)
                pad = data_.xpos[tcp] + R @ np.asarray(gf["pad_center_in_tcp"], float)
                bxy = data_.qpos[bj:bj + 2].copy()
                bz = float(data_.qpos[bj + 2])
                S["rows"].append({"tick": frame, "t": float(data_.time), "pad": pad[:2].copy(), "pad_z": float(pad[2]), "beaker_xy": bxy, "beaker_z": bz,
                                  "sh": data_.xanchor[jan[0]][:2].copy(), "el": data_.xanchor[jan[1]][:2].copy(), "wr": data_.xanchor[jan[2]][:2].copy()})
            if frame == close_tick:
                S["grasp_xy"] = data_.qpos[bj:bj + 2].copy()
            if frame == tick1:
                S["place_xy"] = data_.qpos[bj:bj + 2].copy()
                S["base_xy_yaw"] = (data_.qpos[0:2].copy(), data_.qpos[3:7].copy())
                S["model_shoulder"] = None
        cfg["replay"]["on_tick_end"] = hook
        S["model"] = model
        return orig(model, data, sources, cfg, viewer)

    replay.run_loop = run_loop
    try:
        rep = replay.replay_run(run_dir / "recording", video="none", quiet=True, max_ticks=tick1 + 2)
    finally:
        replay.run_loop = orig
    rows = [r for r in S["rows"] if r["tick"] >= tick0]
    apex = rows[0]["sh"]
    p0, p1 = S["grasp_xy"], S["place_xy"]
    out = {"replay_ok_to_tick": rep["ok"], "ticks": [tick0, tick1], "apex_shoulder_xy": apex.round(4).tolist(), "grasp_xy": p0.round(4).tolist(), "place_xy": p1.round(4).tolist(),
           "shoulder_moved_mm": 1000 * float(max(np.hypot(*(r["sh"] - apex)) for r in rows))}
    rim = 0.5 * BEAKER_CFG["outer_diameter"]
    worst = {"hand (pad centre)": 0.0, "beaker bottom centre": 0.0, "beaker bottom rim": 0.0, "forearm (elbow to wrist)": 0.0}
    r_hand = []
    for r in rows:
        worst["hand (pad centre)"] = max(worst["hand (pad centre)"], slice_distance(r["pad"], apex, p0, p1))
        worst["beaker bottom centre"] = max(worst["beaker bottom centre"], slice_distance(r["beaker_xy"], apex, p0, p1))
        for ang in np.linspace(0, 2 * math.pi, 24, endpoint=False):
            worst["beaker bottom rim"] = max(worst["beaker bottom rim"], slice_distance(r["beaker_xy"] + rim * np.array([math.cos(ang), math.sin(ang)]), apex, p0, p1))
        for f in np.linspace(0.0, 1.0, 11):
            worst["forearm (elbow to wrist)"] = max(worst["forearm (elbow to wrist)"], slice_distance(r["el"] + f * (r["wr"] - r["el"]), apex, p0, p1))
        r_hand.append(float(np.hypot(*(r["pad"] - apex))))
    out["largest_distance_outside_slice_mm"] = {k: round(1000 * v, 2) for k, v in worst.items()}
    pads = np.array([r["pad"] for r in rows])
    seg = p1 - p0
    L2 = float(seg @ seg)
    line_dev = max(float(np.hypot(*(q - (p0 + min(max(float((q - p0) @ seg) / L2, 0.0), 1.0) * seg)))) for q in pads)
    r0, r1 = float(np.hypot(*(p0 - apex))), float(np.hypot(*(p1 - apex)))
    out["hand_path"] = {"radius_from_shoulder_mm": {"at_grasp": round(1000 * r0, 1), "at_set_down": round(1000 * r1, 1), "min": round(1000 * min(r_hand), 1), "max": round(1000 * max(r_hand), 1)},
                        "largest_distance_from_the_straight_line_mm": round(1000 * line_dev, 1), "pad_xy_start_end": [pads[0].round(4).tolist(), pads[-1].round(4).tolist()],
                        "pad_height_m": [round(min(r["pad_z"] for r in rows), 4), round(max(r["pad_z"] for r in rows), 4)],
                        "beaker_bottom_height_m": [round(min(r["beaker_z"] for r in rows), 4), round(max(r["beaker_z"] for r in rows), 4)]}
    # the slice as the selection would build it: from the stance and the robot geometry, against the measured shoulder
    return out, S


def main():
    res = {}
    for name, d in RUNS.items():
        out, S = measure(d)
        res[name] = out
        print(name, json.dumps(out, indent=1), flush=True)
    Path("docs/reports/logs").mkdir(parents=True, exist_ok=True)
    tmp = Path("docs/reports/logs/carry_slice_check.json.tmp")
    tmp.write_text(json.dumps(res, indent=1))
    tmp.replace(Path("docs/reports/logs/carry_slice_check.json"))


if __name__ == "__main__":
    main()
